import {setupSync} from './sync-ui.js';
import {picture,pictureWords,hasPicture,routeScene,connectionScene,locationArt} from './visuals.js';
import {visualLessons,coachScene,hiddenScenes} from './coach.js';
import {chapters,sources,modes,cards,pegs,suits,ranks} from './curriculum.js';
import {DAY,uid,initialStore,newProfile,validStore,generate,score,assessMastery,recommendCount,recordSession,dueReviews,shuffle,match,updateNote,localDay} from './engine.js';
const KEY='mentalist-memory.v1';
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let storageWarning='',state;
try{const raw=localStorage.getItem(KEY);if(raw){const parsed=JSON.parse(raw);if(!validStore(parsed))throw Error('Invalid saved data');state=parsed;}else state=initialStore();}catch(e){state=initialStore();storageWarning='Saved progress could not be read. Export or restore a backup in Settings. This session will not overwrite the unreadable save.';}
let syncUI=null,lastStored=null;try{lastStored=localStorage.getItem(KEY);}catch{}
function commitState(next){if(storageWarning)throw Error(storageWarning);if(localStorage.getItem(KEY)!==lastStored)throw Error('Progress changed in another tab. Reload this tab before continuing.');const raw=JSON.stringify(next);localStorage.setItem(KEY,raw);lastStored=raw;state=next;}
let coachStep=0,coachPlaying=false,coachRevealed=false,studyMotion=false,selectedMotion='bump';
let page='today',lessonId=null,toolTab='routes',active=null,modal='',codeDrill=null,noteReview=null,timer=null,focused=false,lessonChoice=null,setupMode=null;
const p=()=>state.profiles.find(x=>x.id===state.active);
function save(){if(storageWarning){toast('Storage is unavailable. Export a backup from Settings to keep this session.');return;}try{commitState(state);}catch(e){storageWarning=e.message||'This browser cannot save more progress. Export a backup from Settings before closing the app.';toast(storageWarning);}}
function toast(message){const t=$('#toast');t.textContent=message;t.style.display='block';clearTimeout(toast.id);toast.id=setTimeout(()=>t.style.display='none',5000);}
const btn=(label,action,extra='',kind='')=>`<button type="button" class="btn ${kind}" data-action="${action}" ${extra}>${label}</button>`;
const heading=(tag,title,desc='')=>`<div class="page-title"><p class="eyebrow">${tag}</p><h1>${title}</h1>${desc?`<p>${desc}</p>`:''}</div>`;
const nextLesson=()=>chapters.flatMap(c=>c.lessons).find(l=>!p().lessons.includes(l.id))||chapters[0].lessons[0];
const seconds=ms=>`${Math.round(ms/1000)}s`;
const pct=a=>`${Math.round(a*100)}%`;
const date=ms=>new Date(ms).toLocaleDateString(undefined,{month:'short',day:'numeric'});
function go(target){stopSpeaking();if(active&&!confirm('Leave this unfinished drill? Completed progress is already saved.'))return;active=null;clearInterval(timer);timer=null;focused=false;document.body.classList.remove('focus');page=target;setupMode=null;lessonChoice=null;render();window.scrollTo({top:0,behavior:'instant'});}
function shell(body){const due=dueReviews(p()).length+p().notes.filter(n=>n.due<=Date.now()).length;const nav=[['today','Today','▦'],['course','Learning path','⌁'],['train','Practice studio','◎'],['toolkit','My toolkit','⌂'],['review','Review queue','↺'],['progress','My progress','▥'],['science','The method','◇']];return `<div class="layout"><aside class="sidebar"><a class="brand" href="#today" data-page="today"><img src="icon.svg" alt=""><b>Mentalist<br>Memory<small>THE ART OF RECALL</small></b></a><button class="mobile-profile" data-page="settings">${esc(p().name)} · Settings</button><nav class="nav" aria-label="Main navigation">${nav.map(([id,label,icon])=>`<button data-page="${id}" class="${page===id||page==='lesson'&&id==='course'?'active':''}" ${page===id?'aria-current="page"':''}><span class="navicon" aria-hidden="true">${icon}</span>${label}${id==='review'&&due?`<span class="navbadge">${due}</span>`:''}</button>`).join('')}</nav><div class="sidebar-footer"><p class="quote">“Give a memory<br>a place to live.”</p><p class="fineprint">Small sessions.<br>Lasting connections.</p><button class="profilebutton" data-page="settings"><span class="avatar">${esc(p().name.slice(0,1).toUpperCase())}</span><span><strong class="small">${esc(p().name)}</strong><br><span class="fineprint">Profile & settings</span></span></button></div></aside><div class="workspace"><header class="topbar"><span>Your personal memory studio</span><span><i class="dot"></i>Progress ${storageWarning?'needs a backup':'saved on this device'}</span></header>${storageWarning?`<div class="storage-warning" role="alert">${esc(storageWarning)}</div>`:''}<main id="main" class="main" tabindex="-1">${body}<p class="footer-note">MENTALIST MEMORY &nbsp; / &nbsp; TRAIN A SKILL. BUILD IT TO LAST.</p></main></div></div>${modal?`<div class="modal-scrim"><section class="modal" role="dialog" aria-modal="true" aria-label="Practice dialog">${modal}</section></div>`:''}`;}
function palaceArt(){return `<svg viewBox="0 0 430 345" role="img" aria-label="A memory route connecting a doorway, a moon, a tree, and a key"><defs><linearGradient id="g" x2="0" y2="1"><stop stop-color="#cbb77c"/><stop offset="1" stop-color="#748574"/></linearGradient></defs><ellipse cx="228" cy="280" rx="164" ry="43" fill="#0e2422"/><path d="M93 250L222 174 360 242 231 318Z" fill="#2f4941" stroke="#5e7664"/><path d="M93 250v13l138 69v-14M231 332l129-76v-14" fill="#233c35" stroke="#5e7664"/><path d="M144 245l54-31 50 26 48-28" stroke="#b39b64" stroke-width="2" stroke-dasharray="4 7" fill="none"/><path d="M122 238V132a54 54 0 0 1 108 0v102l-20-11V134a34 34 0 0 0-68 0v116Z" fill="url(#g)"/><path d="M142 250V134a34 34 0 0 1 68 0v89" fill="#142c29" stroke="#d8c384"/><path d="M151 246V138a25 25 0 0 1 50 0v92" fill="none" stroke="#6c8064"/><path d="M171 244v-98l18-9v96Z" fill="#405447"/><circle cx="185" cy="195" r="2" fill="#dfbf71"/><circle cx="309" cy="88" r="30" fill="#e3ca87"/><circle cx="320" cy="77" r="26" fill="#182e2b"/><path d="M284 227v-52" stroke="#ad9466" stroke-width="6"/><path d="M252 184q0-30 31-49 38 14 34 48-4 27-33 24-35 1-32-23" fill="#688570"/><path d="M282 194l-16-18m18 9l18-16" stroke="#c2bd85" fill="none"/><circle cx="232" cy="263" r="9" stroke="#e2c17c" stroke-width="5" fill="none"/><path d="M239 270l18 12m-5-5l-4 6" stroke="#e2c17c" stroke-width="5"/><circle cx="91" cy="104" r="3" fill="#b99e66"/><path d="M266 52v9m-5-4h10M351 157v9m-5-4h10M87 195v9m-5-4h10" stroke="#819475"/><text x="159" y="288" fill="#c0c3a3" font-size="9" letter-spacing="3">SEE · PLACE · RECALL</text></svg>`;}
function today(){const pr=p(),lesson=nextLesson(),mastered=chapters.filter(c=>assessMastery(pr,c).mastered).length;const due=dueReviews(pr).length;const dates=new Set(pr.history.map(h=>localDay(h.at)));const latest=pr.history.slice(-5),avg=latest.length?latest.reduce((s,h)=>s+h.accuracy,0)/latest.length:null;return `<div class="intro"><p class="eyebrow" style="margin:0">YOUR NEXT SMALL STEP</p><span class="pill">${pr.minutes}-minute session · At your pace</span></div><section class="hero"><div class="hero-copy"><p class="eyebrow">THE ART OF REMEMBERING</p><h1>See it happen.<br>Learn it one step at a time.</h1><p>Pictures, movement, and short spoken explanations. We will show you the connection, then help you practice it.</p>${btn(pr.lessons.length?'Continue your journey <span>↗</span>':'Begin your journey <span>↗</span>','lesson',`data-id="${lesson.id}"`,'gold')}<p class="footnote">${pr.lessons.length?esc(lesson.title):'Start with one picture. No vivid mental imagery needed.'}</p></div><div class="hero-art">${palaceArt()}</div></section><div class="stats"><div class="stat"><span>LESSONS UNDERSTOOD</span><strong>${pr.lessons.length}<small> / 24</small></strong><span>A foundation to build on</span></div><div class="stat"><span>RECENT ACCURACY</span><strong>${avg===null?'—':pct(avg)}</strong><span>${avg===null?'Your first drill sets the starting point':'Last five drills · mixed tasks'}</span></div><div class="stat"><span>PRACTICE DAYS</span><strong>${dates.size}</strong><span>Every return is useful</span></div><div class="stat"><span>RETESTS DUE</span><strong>${due}</strong><span>${due?'Recall before you re-study':'Retention takes time'}</span></div></div><div class="dashboard-grid"><section><div class="sectionhead"><h2>Your practice, today</h2><span class="small muted">See it · Do it · Recall it</span></div><div class="card"><div class="step"><span class="step-num">01</span><div><h3>Recover something you learned</h3><p>${due?`${due} delayed retest${due>1?'s':''} ready`:'Start a drill to schedule your first retest'}</p></div><button class="linkbtn step-end" data-page="review">Review ↗</button></div><div class="step"><span class="step-num">02</span><div><h3>${esc(lesson.title)}</h3><p>Understand the idea. See it in action.</p></div><button class="linkbtn step-end" data-action="lesson" data-id="${lesson.id}">Learn ↗</button></div><div class="step"><span class="step-num">03</span><div><h3>Put the method into practice</h3><p>A fresh list, hidden answers, useful feedback.</p></div><button class="linkbtn step-end" data-action="setup" data-mode="${lesson.mode}">Train ↗</button></div></div></section><section><div class="sectionhead"><h2>Build your foundations</h2><span class="small muted">${mastered} / 8 skills</span></div><div class="card soft-card"><p class="eyebrow">ACCURACY BEFORE SPEED</p><h3>Make it reliable.<br>Then make it faster.</h3><p class="muted">Mastery combines fresh challenges with later recall. A completed lesson is only the beginning.</p>${chapters.slice(0,3).map(c=>{const n=c.lessons.filter(l=>pr.lessons.includes(l.id)).length;return `<div class="skillline"><span>${c.title}</span><span>${n}/3 lessons</span></div><div class="bar"><span style="width:${n/3*100}%"></span></div>`;}).join('')}<button class="linkbtn" data-page="course" style="margin-top:18px">Explore the learning path →</button></div></section></div>`;}
function course(){return heading('FROM FIRST PRINCIPLES','Your path to reliable recall.','Eight chapters. Twenty-four lessons. Start at the beginning, revisit any idea, and advance through evidence of your own recall.')+`<div class="grid">${chapters.map((c,i)=>{const m=assessMastery(p(),c);return `<article class="card chapter"><div class="row between"><div class="chapter-icon">${c.icon}</div>${m.mastered?'<span class="chip">Mastery target met</span>':''}</div><p class="eyebrow">CHAPTER ${String(i+1).padStart(2,'0')}${i===6?' · OPTIONAL EXTENSION':''}</p><h2>${c.title}</h2><p class="muted">${c.subtitle}</p><ul>${c.lessons.map(l=>`<li><button data-action="lesson" data-id="${l.id}">${p().lessons.includes(l.id)?'✓':'○'} &nbsp;${l.title}</button></li>`).join('')}</ul><div class="milestone">Target: ${c.target} ${c.mode==='numbers'?'pairs of digits':c.mode==='names'?'names':c.mode==='cards'?'cards':c.mode==='pairs'?'associations':'items'} · ${m.fresh}/3 fresh passes</div>${btn('Open chapter →','lesson',`data-id="${c.lessons.find(l=>!p().lessons.includes(l.id))?.id||c.lessons[0].id}"`,'light small')}</article>`;}).join('')}</div><p class="fineprint" style="margin-top:20px">Explore freely. “Mastery target met” requires all chapter checks, three fresh unaided drills at ≥90% at target length across two local dates, and one ≥90% unaided retest at least 24 hours after study. These are app practice targets, not research-validated certification.</p>`;}
function lesson(){
 const c=chapters.find(c=>c.lessons.some(l=>l.id===lessonId))||chapters[0],l=c.lessons.find(l=>l.id===lessonId)||c.lessons[0],index=c.lessons.indexOf(l),slides=visualLessons[l.id],frame=slides[coachStep],chosen=lessonChoice!==null,correct=lessonChoice===l.answer;
 return `<button class="linkbtn" data-page="course">← Learning path</button><div class="visual-lesson"><div class="coach-heading"><div><p class="eyebrow">${c.title} · LESSON ${index+1}</p><h1>${l.title}</h1></div><span class="pill">Pictures first</span></div><section class="visual-coach"><div class="coach-stepbar">${slides.map((x,i)=>`<button type="button" data-action="coach-step" data-index="${i}" class="${coachStep===i?'current':''}" aria-label="Show step ${i+1}" ${coachStep===i?'aria-current="step"':''}><b>${i+1}</b><span>${['See it','Connect it','Recall it'][i]}</span></button>`).join('')}</div><div class="coach-stage ${coachPlaying?'is-playing':''}">${coachScene(frame.scene,coachPlaying,coachRevealed)}</div><div class="coach-caption"><h2>${frame.title}</h2><p id="narration-text">${frame.caption}</p></div><div class="coach-controls"><div class="row">${btn('◖ Listen','listen-coach','','outline small')}${hiddenScenes.has(frame.scene)?btn(coachRevealed?'Hide again':'Show me again','coach-reveal','','light small'):btn(coachPlaying?'Reset example':'▶ Play example','coach-play','','light small')}</div><div class="row">${coachStep>0?btn('← Back','coach-step',`data-index="${coachStep-1}"`,'outline small'):''}${coachStep<2?btn('Next picture →','coach-step',`data-index="${coachStep+1}"`):btn('Try it myself →','setup',`data-mode="${l.mode}"`)}</div></div></section><p class="visual-reassurance">${picture('eye')} <span>Use the pictures on screen. Point, say the connection, or follow the action. A vivid picture inside your head is not required.</span></p>${coachStep===2||p().lessons.includes(l.id)?`<section class="card quick-check"><p class="eyebrow">ONE QUICK CHECK</p><h3>${l.question}</h3>${l.options.map((o,i)=>`<button class="option ${chosen&&i===lessonChoice?(correct?'correct':'wrong'):''}" data-action="answer-lesson" data-index="${i}">${o}</button>`).join('')}${chosen?`<div class="feedback" role="status">${correct?'✓ Exactly.':'Try that once more.'} ${l.feedback}</div>`:''}${correct||p().lessons.includes(l.id)?btn(index<2?'Next lesson →':'Next chapter →','next-lesson',`data-id="${l.id}"`,'light'):''}</section>`:''}<details class="card read-more"><summary>More explanation, if you want it</summary><h3>${l.principle}</h3><p>${l.explanation}</p><p>${l.example}</p><p>${l.action}</p></details></div>`;
}
function train(){if(active)return sessionView();if(setupMode)return setupView();return heading('DELIBERATE PRACTICE','The practice studio.','Choose one skill. Create a connection, hide the answers, and find out what you can recover. Start with three pictures and no time limit.')+`<div class="grid">${Object.entries(modes).map(([id,m])=>`<article class="card"><div class="mode-icon">${m.icon}</div><h2 style="font-size:25px">${m.title}</h2><p class="muted">${m.description}</p><div class="row between"><span class="small muted">${id==='numbers'?'3–50 digit pairs':`3–${m.max} items`}</span>${btn('Practice →','setup',`data-mode="${id}"`,'light small')}</div></article>`).join('')}</div>`;}
function setupView(){const id=setupMode,m=modes[id],recommended=p().history.length?recommendCount(p(),id):3;return `<button class="linkbtn" data-action="studio">← All practice modes</button>`+heading('PREPARE YOUR PRACTICE',m.title,m.description)+`<div class="card" style="max-width:740px"><h3>One small challenge at a time.</h3><p class="muted">One picture at a time. Watch, point, or listen. Choose how much help you want when recalling.</p><div class="support-steps"><span>1. See the example</span><span>2. Build a connection</span><span>3. Try to remember</span></div><form id="setup-form"><label class="field">Recall support<select id="response-mode"><option value="choices">Choose pictures or answers · guided</option><option value="typed">Type answers without choices · independent</option></select></label><div class="formrow"><label class="field">${id==='numbers'?'Number of two-digit pairs':'Number of items'}<input id="count" type="number" min="3" max="${m.max}" value="${id==='palace'?Math.min(recommended,p().routes[0].locations.length):recommended}" required></label><label class="field">Study time<select id="limit"><option value="0">Self-paced · recommended</option value="30">30 seconds</option><option value="60">1 minute</option><option value="120">2 minutes</option><option value="300">5 minutes</option></select></label><label class="field">Session size<select id="minutes"><option value="5" ${p().minutes===5?'selected':''}>5 minutes · gentle</option><option value="10" ${p().minutes===10?'selected':''}>10 minutes · standard</option><option value="15" ${p().minutes===15?'selected':''}>15 minutes · extended</option></select></label></div>${id==='palace'?`<label class="field">Memory route<select id="route">${p().routes.map(r=>`<option value="${r.id}">${esc(r.name)} · ${r.locations.length} locations${p().reviews.some(v=>v.routeId===r.id)?' · reserved for retest':''}</option>`).join('')}</select></label><button type="button" class="linkbtn" data-page="toolkit">Build or extend a route →</button>`:''}${id==='numbers'||id==='cards'||id==='pegs'?`<div class="callout"><p class="eyebrow">BUILD THE COMPONENTS FIRST</p><p>${id==='numbers'?'Use a consistent 00–99 image code. During study you can see your images; during recall you will produce the original two-digit pairs.':id==='cards'?'Each card has a stable image in your toolkit. During recall enter card codes, such as AS (ace of spades) or 10H (ten of hearts).':'Learn your ten permanent peg images before attaching new objects. Recall will ask for positions in a different order.'}</p><button class="linkbtn" type="button" data-action="tool-tab" data-tab="${id}">Open the codebook →</button></div>`:''}<div id="form-error" class="bad small" role="alert"></div><button class="btn" type="submit">Begin visual practice →</button><p class="fineprint" style="margin:16px 0 0">Picture choices build confidence. Independent recall counts toward mastery. Pause anytime; finish the drill to save the result.</p></form></div>`;}
function portrait(n){const skins=['#efd0ac','#bd845f','#7e533c','#d9a57e','#9b6746','#f0d0b4'],hair=['#2b2824','#6a4330','#b18548','#33312a'],shirts=['#51776e','#b97955','#657b9b','#9c8f53','#8e6692','#768c54'];return `<svg class="portrait" viewBox="0 0 100 110" role="img" aria-label="Illustrated person"><rect width="100" height="110" rx="16" fill="${['#e4e8dc','#e9e1d1','#e1e6ed','#ece0d9'][n%4]}"/><path d="M13 112v-12q2-24 37-24t37 24v12" fill="${shirts[n%6]}"/><rect x="42" y="65" width="16" height="24" rx="7" fill="${skins[n%6]}"/><ellipse cx="50" cy="45" rx="25" ry="32" fill="${skins[n%6]}"/><path d="M25 43V29Q27 6 51 8q29 0 26 33l-10-16q-21 7-36-1Z" fill="${hair[Math.floor(n/6)%4]}"/>${n%3===0?'<path d="M25 31v35l-8 9 6-50ZM75 31v35l8 9-6-50Z" fill="'+hair[Math.floor(n/6)%4]+'"/>':''}<circle cx="40" cy="46" r="2" fill="#262724"/><circle cx="60" cy="46" r="2" fill="#262724"/><path d="M47 53l-2 7 8 1M42 69q8 6 16-1" stroke="#744e3c" fill="none" stroke-linecap="round"/>${n%2===0?'<g fill="none" stroke="#33463f" stroke-width="2"><rect x="30" y="39" width="17" height="13" rx="5"/><rect x="53" y="39" width="17" height="13" rx="5"/><path d="M47 44h6"/></g>':''}${n%4===1?'<circle cx="26" cy="60" r="3" fill="#c7a458"/><circle cx="74" cy="60" r="3" fill="#c7a458"/>':''}<path d="M37 85l13 10 13-10" fill="none" stroke="#ffffff66" stroke-width="3"/></svg>`;}
function begin(mode,count,limit,routeId){try{const responseMode=$('#response-mode')?.value==='typed'?'typed':'choices';const set=generate(mode,count,p(),{routeId,visual:true,responseMode});active={studyIndex:0,recallIndex:0,placed:[],choices:makeChoices(set),set,phase:'study',start:Date.now(),studyStart:Date.now(),encodingMs:0,recallStart:0,recallMs:0,limit,remaining:limit*1000,paused:false,assisted:false,answers:Array(set.count).fill(''),reviewId:null};page='train';setupMode=null;render();startClock();}catch(e){$('#form-error').textContent=e.message;}}
function startClock(){clearInterval(timer);timer=setInterval(()=>{if(!active||active.paused||active.phase==='result')return;const now=Date.now();const t=$('#clock');if(active.phase==='study'){const elapsed=now-active.studyStart;if(t)t.textContent=active.limit?seconds(Math.max(0,active.remaining-elapsed)):seconds(active.encodingMs+elapsed);if(active.limit&&elapsed>=active.remaining)toRecall();}else if(t)t.textContent=seconds(active.recallMs+now-active.recallStart);const reminder=$('#session-reminder');if(reminder&&now-active.start>=p().minutes*60000)reminder.textContent='You have reached your session goal. Finish this drill, or pause and take a break.';},250);}
function captureAnswers(){if(active?.phase==='recall')document.querySelectorAll('[data-answer]').forEach(i=>active.answers[Number(i.dataset.answer)]=i.value);}
function toRecall(){stopSpeaking();if(!active||active.phase!=='study')return;active.encodingMs+=Date.now()-active.studyStart;active.phase='recall';active.recallIndex=0;active.recallStart=Date.now();active.paused=false;render();$('#answer-0')?.focus();}
function togglePause(){stopSpeaking();captureAnswers();const a=active,now=Date.now();if(a.paused){a.paused=false;if(a.phase==='study')a.studyStart=now;else a.recallStart=now;}else{a.paused=true;if(a.phase==='study'){const elapsed=now-a.studyStart;a.encodingMs+=elapsed;if(a.limit)a.remaining=Math.max(0,a.remaining-elapsed);}else a.recallMs+=now-a.recallStart;}render();}
function sessionView(){
 const a=active,s=a.set;if(a.phase==='result')return resultsView();const study=a.phase==='study',pos=study?(a.studyIndex||0):(a.recallIndex||0),idx=study?pos:s.order[pos],item=s.items[idx],guided=s.responseMode==='choices';
 return `<div class="training-wrap visual-practice"><div class="trainingtop"><div><p class="eyebrow" style="margin:0 0 7px">${modes[s.mode].title}</p><span class="phase">${a.reviewId?'DELAYED RETEST':study?'SEE & CONNECT':'RECALL'} · ${guided?'GUIDED CHOICES':'INDEPENDENT'} ${a.assisted?'· ASSISTED PRACTICE':''}</span></div><div class="row"><span id="clock" class="timer">${study&&a.limit?seconds(a.remaining):'0s'}</span>${btn(a.paused?'Resume':'Pause','pause','','outline small')}${btn(focused?'Exit focus':'Focus','focus','','outline small')}</div></div>${a.paused?`<div class="card empty"><h2>Take a breath.</h2><p class="muted">The pictures are hidden. Your timer is paused.</p>${btn('Resume practice','pause')}</div>`:`<section class="visual-drill-card"><div class="visual-drill-head"><span class="pill">${study?'Picture':'Question'} ${pos+1} of ${s.items.length}</span><div class="tiny-dots" aria-label="${pos+1} of ${s.items.length}">${s.items.map((_,i)=>`<i class="${i===pos?'active':''}"></i>`).join('')}</div></div>${study?studyPictureView(s,item,idx):recallPictureView(s,item,idx,pos)}<div class="coach-controls"><div class="row">${study?btn('◖ Listen','listen-study','','outline small'):btn('Need another look?','another-look','','outline small')}</div><div class="row">${pos>0?btn('← Back',study?'study-back':'recall-back','','outline small'):''}${study?(pos<s.items.length-1?btn('Next picture →','study-next'):btn('Hide & recall →','recall')):(pos<s.items.length-1?btn('Next →','recall-next'):btn('Check my recall →','submit-recall'))}</div></div></section>`}<p id="session-reminder" class="fineprint" role="status" style="margin-top:16px"></p></div>`;
}
function studyPictureView(s,item,idx){
 const previous=s.items[idx-1];let visual='',caption='';
 if(s.mode==='pairs'){visual=connectionScene(item.cue,item.answer,selectedMotion,studyMotion);caption=`${item.cue} connects to ${item.answer}. Say the link or watch it move.`;}
 else if(s.mode==='words'&&previous){visual=connectionScene(previous.answer,item.answer,selectedMotion,studyMotion);caption=`${previous.answer} → ${item.answer}. Connect this picture to the one before it.`;}
 else if(s.mode==='palace'){const locs=s.items.map(i=>i.cue),shown=s.items.map((i,n)=>active.placed.includes(n)?i.answer:null);visual=`<div class="palace-study-object">${picture(item.answer,{label:true})}</div>${routeScene(locs,shown,idx)}`;caption=`Put ${item.answer} at ${item.cue}. The place becomes a cue.`;}
 else if(s.mode==='pegs'){visual=`<div class="peg-example"><span class="number-disc">${idx+1}</span>${connectionScene(item.hint,item.answer,selectedMotion,studyMotion)}</div>`;caption=`Item ${idx+1}: ${item.hint} helps you retrieve ${item.answer}.`;}
 else if(s.mode==='names'){visual=`<div class="visual-name">${portrait(item.face)}<div class="name-label">${esc(item.answer)}</div></div>`;caption=`Say “${item.answer}.” Notice one detail on this person. Make a sound or meaning connection.`;}
 else if(s.mode==='numbers'){visual=`<div class="coach-row"><span class="number-disc">${esc(item.answer)}</span><b>↔</b>${picture(item.hint,{label:true})}</div>`;caption=`${item.answer} means ${item.hint} in your code. Say it and point to the picture.`;}
 else if(s.mode==='cards'){visual=`<div class="coach-row"><div class="playingcard ${item.red?'red':''}">${esc(item.card)}</div><b>↔</b>${picture(item.hint,{label:true})}</div>`;caption=`${item.answer} connects to ${item.hint}. Keep it at position ${idx+1}.`;}
 else{visual=`<div class="single-picture">${picture(item.answer,{label:true})}</div>`;caption=`First, notice ${item.answer}. Say its name. You can use the picture on screen.`;}
 return `<div class="practice-picture-stage ${studyMotion?'is-playing':''}">${visual}</div><div class="coach-caption"><h2>${s.mode==='names'?'Meet one person.':s.mode==='palace'?'Give it a place.':s.mode==='numbers'||s.mode==='cards'?'Learn the connection.':`Position ${idx+1}`}</h2><p id="study-caption">${caption}</p></div>${s.mode==='palace'?`<div class="row center">${btn(active.placed.includes(idx)?'Placed ✓':'Place this picture','place-picture','','light')}</div>`:['pairs','words','pegs'].includes(s.mode)?`<div class="motion-controls"><span>Try an action:</span>${['bump','lift','spin'].map(v=>`<button type="button" data-action="animate-pair" data-motion="${v}" class="${selectedMotion===v&&studyMotion?'selected':''}">${v==='bump'?'Bump together':v==='lift'?'Lift up':'Spin around'}</button>`).join('')}</div>`:''}`;
}
function recallPictureView(s,item,idx,pos){const a=active,guided=s.responseMode==='choices';let cue=s.mode==='pairs'?picture(item.cue,{label:true}):s.mode==='names'?portrait(item.face):`<span class="number-disc">${idx+1}</span>`;const question=s.mode==='pairs'?'What was connected to this?':s.mode==='names'?'What is this person’s name?':s.mode==='palace'?'What was at this place in your route?':s.mode==='pegs'?'What was at this numbered position?':s.mode==='numbers'?'Which two digits were here?':s.mode==='cards'?'Which card was here?':'Which picture was in this position?';
 return `<div class="recall-cue">${cue}</div><div class="coach-caption"><h2>${question}</h2><p>${guided?'Tap one answer. We will check after the whole set.':'Produce the answer before checking. The pictures stay hidden.'}</p></div>${guided?`<div class="picture-choices" role="group" aria-label="Answer choices">${a.choices[idx].map(x=>`<button type="button" data-action="choose-picture" data-answer-value="${esc(x.answer)}" aria-pressed="${a.answers[idx]===x.answer}" class="picture-choice ${a.answers[idx]===x.answer?'selected':''}">${s.mode==='cards'?`<div class="playingcard ${x.red?'red':''}">${esc(x.card||x.answer)}</div>`:s.mode==='numbers'?`<span class="choice-digits">${esc(x.answer)}</span>`:s.mode==='names'?`<span class="choice-name">${esc(x.answer)}</span>`:picture(x.answer,{label:true})}<span class="choice-check" aria-hidden="true">${a.answers[idx]===x.answer?'✓':''}</span></button>`).join('')}</div>`:`<div class="typed-recall"><label class="field">${s.mode==='cards'?'Card code, such as AS or 10H':s.mode==='numbers'?'Two digits, including any leading zero':'Your answer'}<input id="answer-${pos}" data-answer="${idx}" value="${esc(a.answers[idx])}" autocomplete="off" autocorrect="off" spellcheck="false" ${s.mode==='numbers'?'inputmode="numeric" maxlength="2"':'maxlength="120"'}></label></div>`}<p class="support-label">${guided?'Guided recognition practice · separate from independent mastery':'Independent recall · eligible for mastery if no answers are revealed'}</p>`;
}
function makeChoices(s){const pool=s.mode==='numbers'?Array.from({length:100},(_,i)=>({answer:String(i).padStart(2,'0')})):s.mode==='cards'?cards.map(c=>({answer:c.code,card:c.display,red:c.red})):s.mode==='names'?['Ava','Eli','Nora','Omar','Zoe','Alex','Rose','Leo','Maya','Sam'].map(answer=>({answer})):pictureWords.map(answer=>({answer}));return s.items.map(target=>shuffle([{...target},...shuffle(pool.filter(i=>i.answer!==target.answer)).slice(0,3)]));}
function stopSpeaking(){if(typeof window!=='undefined'&&window.speechSynthesis)window.speechSynthesis.cancel();}
function speak(text){if(!window.speechSynthesis||typeof window.SpeechSynthesisUtterance!=='function'){toast('Audio is unavailable in this browser. The short caption stays on screen.');return;}stopSpeaking();const utterance=new window.SpeechSynthesisUtterance(text);utterance.rate=.88;utterance.lang='en-US';utterance.onerror=()=>toast('Audio could not play. You can keep using the pictures and captions.');window.speechSynthesis.speak(utterance);}
function studyInstructions(mode){return {pairs:'Use the first word as a cue for the second. Imagine an action between them. During recall, only the cue will appear.',words:'Link each word to the next with an action. Recover the words in their original order.',palace:'Visit each location in order. Make the item interact with the location. During recall, location labels will be hidden.',pegs:'Connect each object to its numbered peg image. Later, the position questions will be shuffled.',numbers:'Each two-digit pair has a stable image. Link the images in order, then decode them back into exact pairs.',names:'Listen to each name in your mind. Connect it to a respectful detail on the portrait. These are illustrated practice faces.',cards:'Associate each card with its image and place the images in order. This is a fresh shuffle, not a fixed deck stack.'}[mode];}
function recallInstructions(mode,review){return (review?'Recall the original set without re-studying. ':'')+({pairs:'The cue words are in a new order. Type the answer associated with each cue.',words:'Follow your chain and type each word in its original position.',palace:'Walk your route mentally. Type the item stored at each position.',pegs:'Each number refers to the original position. Use its permanent peg to retrieve the object.',numbers:'Type two digits per position, including leading zeroes: 01 and 10 are different.',names:'The portraits are shuffled. Type the original name for each person.',cards:'Type rank + suit: AS, 2H, 10D, QC. Suits: S spades, H hearts, D diamonds, C clubs. A is ace; J, Q, K are the face cards.'}[mode]);}
function itemView(item,idx,pos,study,mode,answer){return `<div class="memory-item">${mode==='names'?portrait(item.face):''}<span class="number">${mode==='pairs'?`CUE · ${esc(item.cue)}`:mode==='palace'&&study?`${idx+1} · ${esc(item.cue)}`:mode==='names'?`PERSON ${pos+1}`:`POSITION ${idx+1}`}</span>${study&&mode!=='names'&&mode!=='cards'?picture(mode==='numbers'?item.hint:item.answer):''}${study?(mode==='cards'?`<div class="playingcard ${item.red?'red':''}">${esc(item.card)}</div>`:`<div class="word">${esc(item.answer)}</div>`):`<label class="small muted" for="answer-${pos}">${mode==='names'?'Name':mode==='numbers'?'Two digits':mode==='cards'?'Card code':'Your answer'}</label><input id="answer-${pos}" data-answer="${idx}" value="${esc(answer)}" autocomplete="off" autocorrect="off" autocapitalize="off" spellcheck="false" ${mode==='numbers'?'inputmode="numeric" maxlength="2"':'maxlength="120"'} aria-label="${mode==='pairs'?'Answer for '+esc(item.cue):mode==='names'?'Name for person '+(pos+1):'Answer for position '+(idx+1)}">`}${study&&item.hint?`<div class="hint">${['numbers','cards','pegs'].includes(mode)?picture(item.hint):''}${esc(mode==='pegs'?'Peg: '+item.hint:item.hint)}</div>`:''}</div>`;}
function submitRecall(){captureAnswers();const a=active;if(a.phase!=='recall'||a.paused)return;a.recallMs+=Date.now()-a.recallStart;a.result=recordSession(p(),a.set,a.answers,{encodingMs:a.encodingMs,recallMs:a.recallMs,assisted:a.assisted,reviewId:a.reviewId});save();a.phase='result';clearInterval(timer);render();window.scrollTo({top:0,behavior:'instant'});}
function resultsView(){const a=active,s=a.set,r=a.result;const good=r.accuracy>=.9;return `<div class="training-wrap">${heading('3. CHECK & REFINE',good?'A strong connection.':'Every miss gives you a clue.',good?'Now see whether it lasts. Accuracy first; speed can follow.':'Find the weak connection, rebuild it, and try fresh material when ready.')}<div class="card"><div class="row" style="gap:28px"><div class="score-ring">${pct(r.accuracy)}</div><div><h3>${r.correct} of ${r.total} recalled correctly</h3><p class="muted">${a.reviewId?`Retest delay: ${(r.history.delayMs/DAY).toFixed(1)} days`:`Study: ${seconds(a.encodingMs)}`} &nbsp;·&nbsp; Recall: ${seconds(a.recallMs)}</p><span class="chip">${a.assisted?'Assisted · not a mastery pass':s.responseMode==='choices'?'Guided recognition · not a mastery pass':a.reviewId?'Delayed recall':'Fresh unaided practice'}</span></div></div><div class="feedback">${a.reviewId&&good&&!a.assisted?'Retest complete. Your result is saved separately from immediate recall.':a.reviewId?'Retest saved. Rebuild the missed associations below; another attempt is due in 24 hours.':'This set is saved for a retest in 24 hours. The app will ask for recall before showing the answers.'}</div><div class="table-scroll"><table class="results"><thead><tr><th>${s.mode==='pairs'?'Cue':'Position'}</th><th>Your answer</th><th>Original answer</th><th>Result</th></tr></thead><tbody>${s.items.map((item,i)=>`<tr><td>${s.mode==='pairs'?esc(item.cue):i+1}</td><td>${esc(a.answers[i])||'—'}</td><td><span class="result-picture">${picture(s.mode==='numbers'||s.mode==='cards'?item.hint:item.answer)}</span>${esc(item.card||item.answer)}${item.hint?`<br><span class="fineprint">${esc(item.hint)}</span>`:''}</td><td class="${r.results[i].correct?'good':'bad'}">${r.results[i].correct?'✓ Correct':'○ Rebuild'}</td></tr>`).join('')}</tbody></table></div><div class="callout"><h3>${good?'Keep the next challenge controlled.':'Repair the connection.'}</h3><p>${good?'Repeat with fresh material. Once accuracy is stable, change only one demand: list length, study time, or retention delay.':'Ask: did I miss the item, mix up the order, or fail to decode the image? Make the cue more specific, shorten the next list if needed, and attempt recall again.'}</p></div><div class="row">${btn('Practice a fresh set','fresh',`data-mode="${s.mode}"`)}${btn('Back to today','finish','','light')}${btn('View my progress','finish-progress','','outline')}</div></div></div>`;}
function review(){const all=[...p().reviews].sort((a,b)=>a.due-b.due),notes=p().notes.filter(n=>n.due<=Date.now());return heading('MAKE IT LAST','Your review queue.','Retrieve first. Then check and repair. Memory-set retests begin 24 hours after study; your own notes use a gradually expanding schedule.')+`<div class="card"><div class="row between"><h2 style="font-size:26px;margin:0">Memory-set retests</h2><span class="chip">${dueReviews(p()).length} ready</span></div>${all.length?all.map(r=>{const ready=r.due<=Date.now();return `<div class="reviewrow"><span class="mode-icon" style="margin:0;flex-shrink:0">${modes[r.mode].icon}</span><div><h3>${modes[r.mode].title} · ${r.items.length} ${r.mode==='numbers'?'pairs':'items'}</h3><p class="muted">${r.routeName?esc(r.routeName)+' · ':''}Studied ${date(r.lastStudyAt)} · ${ready?'Ready to retrieve':`Due ${new Date(r.due).toLocaleString(undefined,{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'})}`}</p></div>${btn(ready?'Recall now →':'Not due yet','review-set',`data-id="${r.id}" ${ready?'':'disabled'}`,'light small')}</div>`;}).join(''):`<div class="empty"><h2>Give your first memory a tomorrow.</h2><p class="muted">Complete a practice drill. Its exact items will be saved for a later recall test.</p>${btn('Start a drill','setup','data-mode="pairs"')}</div>`}</div><div class="card" style="margin-top:22px"><h2 style="font-size:26px">My notebook</h2><p class="muted">Turn what you are learning into questions. Note reviews are self-assessed and are separate from scored memory drills.</p><div class="row">${notes.length?btn(`Review ${notes.length} due note${notes.length>1?'s':''}`,'review-note',`data-id="${notes[0].id}"`):'<span class="small muted">No notes due right now.</span>'}${btn('Open notebook →','tool-tab','data-tab="notes"','outline')}</div></div>`;}
function toolkit(){return heading('YOUR RETRIEVAL INFRASTRUCTURE','Make the method your own.','Build familiar routes and consistent codes. Start small, learn them in both directions, and expand when they feel reliable.')+`<div class="tabs" role="group" aria-label="Toolkit sections">${[['routes','Memory routes'],['pegs','Ten pegs'],['numbers','00–99 code'],['cards','Card code'],['pao','PAO builder'],['notes','My notebook']].map(([id,title])=>`<button data-action="tool-tab" data-tab="${id}" class="${toolTab===id?'active':''}">${title}</button>`).join('')}</div>${({routes:routesView,pegs:pegsView,numbers:numbersView,cards:cardsView,pao:paoView,notes:notesView}[toolTab]||routesView)()}`;}
function routesView(){return `<div class="grid two"><div class="card"><h2>Build a familiar route</h2><p class="muted">Choose 3–5 familiar places. Keep them in one fixed order.</p><form id="route-form"><label class="field">Route name<input name="name" required maxlength="60" placeholder="e.g. My morning walk"></label><label class="field">Locations, in order<textarea name="locations" required rows="7" placeholder="Front gate&#10;Mailbox&#10;Oak tree&#10;Garden bench&#10;Back door"></textarea></label><div class="bad small" id="route-error" role="alert"></div><button class="btn" type="submit">Save route</button></form></div><div>${p().routes.map(r=>`<article class="card" style="margin-bottom:18px"><div class="row between"><h3>${esc(r.name)}</h3><span class="chip">${r.locations.length} locations</span></div><p class="fineprint">${p().reviews.some(v=>v.routeId===r.id)?'Reserved for a pending retest. Use a different route for fresh lists.':'Available for a fresh palace practice.'}</p>${routeScene(r.locations,[],0)}<div class="row">${btn('Practice route','route-practice',`data-id="${r.id}"`,'light small')}${btn('Edit','route-edit',`data-id="${r.id}"`,'outline small')}</div></article>`).join('')}</div></div>`;}
function pegsView(){return `<div class="card"><h2>Ten permanent pegs</h2><p class="muted">Keep these stable while you attach new objects. Rhyme cues are a starting option; use a different cue if it is clearer to you.</p><form id="peg-form"><div class="code-grid">${p().pegs.map((v,i)=>`<label class="illustrated-code"><b>${i+1}</b>${picture(v)}<input name="peg-${i}" value="${esc(v)}" required maxlength="120" aria-label="Peg ${i+1}"></label>`).join('')}</div><div class="row" style="margin-top:22px"><button class="btn" type="submit">Save pegs</button>${btn('Practice both directions','code-setup','data-code="pegs"','light')}</div></form></div>`;}
function numbersView(){return `<div class="card"><h2>Your 00–99 images</h2><p class="muted">A Major-derived starter code. Use consonant sounds, not letters; choose words that fit your pronunciation. Custom images may be any fixed associations. Learn one ten-number batch at a time.</p><div class="callout"><p class="small" style="margin:0">0 s/z · 1 t/d · 2 n · 3 m · 4 r · 5 l · 6 sh/ch/j/soft g · 7 k/hard g · 8 f/v · 9 p/b<br>Vowels fill the gaps. Examples: 12 → tin; 32 → moon; 28 → knife (silent k).</p></div><form id="number-form"><div class="code-grid">${p().numberImages.map((v,i)=>`<label class="illustrated-code"><b>${String(i).padStart(2,'0')}</b>${picture(v)}<input name="num-${i}" value="${esc(v)}" required maxlength="120" aria-label="Image for ${String(i).padStart(2,'0')}"></label>`).join('')}</div><div class="row" style="margin-top:22px"><button class="btn" type="submit">Save number images</button>${btn('Train the code','code-setup','data-code="numbers"','light')}</div></form><p class="fineprint" style="margin-top:16px">Pending retests preserve the original study images. Changing a code can still cause mental interference; change it deliberately.</p></div>`;}
function cardsView(){return `<div class="card"><h2>52 cards, 52 images</h2><p class="muted">This is a fixed object code. Train each card-to-image and image-to-card pairing before memorizing longer shuffles. S = spades, H = hearts, D = diamonds, C = clubs.</p><form id="card-form">${suits.map(([s,symbol,name],si)=>`<h3 style="margin:23px 0 12px">${symbol} ${name}</h3><div class="code-grid">${cards.slice(si*13,si*13+13).map((c,ri)=>`<label class="illustrated-code"><b class="${c.red?'red':''}">${c.display}</b>${picture(p().cardImages[si*13+ri])}<input name="card-${si*13+ri}" value="${esc(p().cardImages[si*13+ri])}" maxlength="120" required aria-label="Image for ${c.code}"></label>`).join('')}</div>`).join('')}<div class="row" style="margin-top:22px"><button class="btn" type="submit">Save card images</button>${btn('Train the code','code-setup','data-code="cards"','light')}</div></form></div>`;}
function paoView(){return `<div class="grid two"><div class="card"><h2>Build one PAO row</h2><p class="muted">An optional advanced system. Keep each person, action, and object distinct. Duplicate components make reverse decoding ambiguous.</p><form id="pao-form"><label class="field">Two-digit code<input name="code" inputmode="numeric" pattern="[0-9]{2}" maxlength="2" placeholder="12" required></label><label class="field">Person<input name="person" placeholder="pilot" maxlength="100" required></label><label class="field">Action<input name="action" placeholder="steering" maxlength="100" required></label><label class="field">Object<input name="object" placeholder="plane" maxlength="100" required></label><button class="btn" type="submit">Save row</button></form><button class="linkbtn" data-action="pao-examples">Add the three lesson examples</button></div><div class="card"><h2>Assemble a scene</h2><p class="muted">Enter six digits. The first pair supplies the person, the middle pair the action, and the last pair the object. Save all three rows first.</p><form id="pao-scene-form"><label class="field">Six digits<input name="digits" inputmode="numeric" pattern="[0-9]{6}" maxlength="6" placeholder="123456" required></label><button class="btn light" type="submit">Build & practice scene</button></form><div id="pao-scene" style="margin-top:20px" role="status"></div><h3 style="margin-top:30px">Your saved rows</h3>${Object.entries(p().pao).length?`<div class="table-scroll"><table class="results"><thead><tr><th>Code</th><th>Person</th><th>Action</th><th>Object</th></tr></thead><tbody>${Object.entries(p().pao).sort().map(([n,v])=>`<tr><td>${esc(n)}</td><td>${esc(v.person)}</td><td>${esc(v.action)}</td><td>${esc(v.object)}</td></tr>`).join('')}</tbody></table></div>`:'<p class="fineprint">No rows yet. Start with 12, 34, and 56 from the lesson.</p>'}<p class="fineprint">PAO drills are component practice and do not award a chapter mastery pass.</p></div></div>`;}
function notesView(){return `<div class="grid two"><div class="card"><h2>Learn something useful</h2><p class="muted">Understand the idea first. Write a question you can answer without seeing the original. Add a mnemonic cue if useful.</p><form id="note-form"><label class="field">Retrieval question<input name="question" required maxlength="300" placeholder="What do I want to be able to recall?"></label><label class="field">Answer<textarea name="answer" required maxlength="2000" placeholder="The exact fact, explanation, or speech outline"></textarea></label><label class="field">My association or location<textarea name="cue" maxlength="1000" placeholder="The image, sound, meaning, or route that will help me"></textarea></label><button class="btn" type="submit">Save to my notebook</button></form><p class="fineprint" style="margin-top:15px">Saved on this device and included in cloud sync when you connect this learner. Avoid sensitive personal details.</p></div><div class="card"><div class="row between"><h2 style="margin:0">My notes</h2><span class="chip">${p().notes.length} saved</span></div>${p().notes.length?p().notes.map(n=>`<article class="note"><h3>${esc(n.question)}</h3><p class="fineprint">${n.due<=Date.now()?'Ready to review':'Due '+date(n.due)} · ${n.reviews||0} reviews</p><details><summary>Show saved answer & cue</summary><p style="white-space:pre-wrap">${esc(n.answer)}</p><p class="muted" style="white-space:pre-wrap">${esc(n.cue)}</p></details>${btn('Practice this note','review-note',`data-id="${n.id}"`,'light small')}</article>`).join(''):'<div class="empty"><p class="muted">Your ideas will live here.</p></div>'}</div></div>`;}
function progress(){const pr=p(),history=pr.history,delayed=history.filter(h=>h.delayed&&!h.assisted&&h.responseMode!=='choices'),fresh=history.filter(h=>!h.delayed&&!h.assisted&&h.responseMode!=='choices'),avg=arr=>arr.length?pct(arr.reduce((s,h)=>s+h.accuracy,0)/arr.length):'—';return heading('EVIDENCE OF YOUR PRACTICE','See what is becoming reliable.','Track immediate recall and delayed retention separately. Compare similar modes, list lengths, and study limits before drawing conclusions.')+`<div class="stats"><div class="stat"><span>COMPLETED DRILLS</span><strong>${history.length}</strong></div><div class="stat"><span>FRESH RECALL</span><strong>${avg(fresh)}</strong><span>Unaided · mixed tasks</span></div><div class="stat"><span>DELAYED RECALL</span><strong>${avg(delayed)}</strong><span>Unaided retests only</span></div><div class="stat"><span>MASTERY TARGETS</span><strong>${chapters.filter(c=>assessMastery(pr,c).mastered).length} / 8</strong></div></div><div class="card"><h2 style="font-size:27px">Skill checkpoints</h2><p class="muted">Three fresh passes at ≥90%, across two dates, plus a ≥24-hour delayed pass. All lesson checks must also be complete. Lower list lengths remain useful practice.</p><div class="grid two">${chapters.map(c=>{const m=assessMastery(pr,c);return `<div><h3>${c.icon} &nbsp;${c.title}</h3><p class="fineprint">${c.target} ${c.mode==='numbers'?'pairs of digits':'items'} · ${m.mastered?'Target met':'In progress'}</p><div class="bar"><span style="width:${(m.fresh/3+m.days/2+Number(m.delayed)+Number(m.lessons))/4*100}%"></span></div><p class="fineprint">${m.fresh}/3 fresh passes · ${m.days}/2 dates · ${m.delayed?'✓':'○'} delayed pass · ${m.lessons?'✓':'○'} lesson checks</p></div>`;}).join('')}</div></div><div class="card" style="margin-top:24px"><h2 style="font-size:27px">Practice log</h2>${history.length?`<div class="table-scroll"><table class="results"><thead><tr><th>Date</th><th>Skill</th><th>Length</th><th>Accuracy</th><th>Study / recall</th><th>Type</th></tr></thead><tbody>${history.slice(-30).reverse().map(h=>`<tr><td>${date(h.at)}</td><td>${modes[h.mode].title}</td><td>${h.count}${h.mode==='numbers'?' pairs':''}</td><td>${pct(h.accuracy)}</td><td>${h.delayed?'—':seconds(h.encodingMs)} / ${seconds(h.recallMs)}</td><td>${h.assisted?'Assisted':h.responseMode==='choices'?'Picture choices':h.delayed?'Delayed':'Fresh'}${h.delayed?` · ${(h.delayMs/DAY).toFixed(1)}d`:''}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty"><p class="muted">No invented scores. Your first completed drill will appear here.</p>'+btn('Start your first drill','setup','data-mode="pairs"')+'</div>'}<div class="row">${btn('Export practice log (CSV)','export-csv','','outline small')}${btn('Back up all progress','export','','outline small')}</div></div>`;}
function science(){return heading('THE METHOD BEHIND THE PRACTICE','Train the craft of remembering.','“Mentalist memory” here means trained recall for useful learning and impressive demonstrations. It does not mean photographic memory or mind reading.')+`<div class="grid two"><article class="card"><h2>From first principles</h2><ol style="padding-left:20px;font-size:14px;line-height:1.9"><li><strong>Attend:</strong> notice the correct information.</li><li><strong>Understand:</strong> know what it means.</li><li><strong>Encode:</strong> connect it to a useful cue.</li><li><strong>Organize:</strong> use a chain, peg, or location.</li><li><strong>Retrieve:</strong> hide it and produce the answer.</li><li><strong>Repair:</strong> check, explain the miss, improve the cue.</li><li><strong>Space:</strong> return after a delay.</li><li><strong>Transfer:</strong> test the skill in the situation that matters.</li></ol><p class="fineprint">Mnemonic systems support encoding and access. Retrieval and spaced practice support lasting learning. None removes the need for understanding or task-specific practice.</p></article><article class="card soft-card"><h2>A practical session</h2><p>Choose 5, 10, or 15 comfortable minutes. Review something due, learn one small idea, and complete one fresh drill. Stop before fatigue turns practice into guessing.</p><p>Use images if they help. You can also use sound, verbal stories, meaningful explanations, touch, or imagined movement. The app does not require vivid visualization.</p><h3>What “mastery” means here</h3><p>Reliable recall at a stated length and delay. The 90% threshold, three-pass rule, chapter targets, and review intervals are design choices, not standardized or validated cutoffs.</p><p class="fineprint">This is educational practice, not a medical treatment or diagnostic test. Broad improvements in intelligence or everyday memory are not established by success on these drills.</p></article></div><div class="card" style="margin-top:24px"><h2>Research that shaped the course</h2>${sources.map(s=>`<article class="note"><h3><a href="${s.url}" target="_blank" rel="noopener noreferrer">${s.title} ↗</a></h3><p class="muted">${s.finding}</p></article>`).join('')}<div class="note"><h3>Your supplied training guide</h3><p class="muted">Mentalist Memory Training Guide supplied the technique inventory and the distinction between foundational systems and advanced applications. This app expands it into instruction, worked examples, practice, feedback, and delayed tests. The original PDF is not redistributed with the app.</p></div><p class="fineprint" style="margin-top:18px">Research reviewed October 18, 2026. The specific app and its curriculum have not been evaluated in a controlled study. Technique examples and all lesson wording are original instructional material.</p></div>`;}
function settings(){return heading('YOUR SPACE','Profile & progress.','Choose a learner, then use the sync section below to share their progress across devices.')+`<div class="grid two"><section class="card"><h2>Your profiles</h2><label class="field">Active learner<select id="profile-select">${state.profiles.map(x=>`<option value="${x.id}" ${x.id===state.active?'selected':''}>${esc(x.name)}</option>`).join('')}</select></label><form id="rename-form"><label class="field">Profile name<input name="name" maxlength="60" value="${esc(p().name)}" required></label><button class="btn light" type="submit">Save name</button></form><form id="new-profile-form" style="border-top:1px solid var(--line);margin-top:25px;padding-top:15px"><label class="field">New learner name<input name="name" maxlength="60" required placeholder="Add another learner"></label><button class="btn outline" type="submit">Create local profile</button></form></section><section class="card"><h2>Keep your progress</h2><p class="muted">Your progress saves on this device first. Connect a sync code below to use another device, or keep an exported backup.</p><div class="row">${btn('Export all progress','export')}${btn('Export log (CSV)','export-csv','','outline')}</div><form id="import-form" style="margin-top:20px"><label class="field">Restore a Mentalist Memory backup<input name="backup" type="file" accept="application/json,.json" required></label><p class="fineprint">Restore imports profiles as new copies, preserving the current profiles. Only valid version 1 backups are accepted. Keep the backup private if it contains personal notes.</p><button class="btn light" type="submit">Import profiles</button></form><div id="import-error" class="bad small" role="alert"></div><h3 style="margin-top:25px">Designed to be calm</h3><p class="fineprint">Practice is self-paced by default. Pause hides material and stops the timer. Focus mode removes navigation. Reduced-motion preferences are respected.</p></section></div>`;}
function render(){const views={today,course,lesson,train,toolkit,review,progress,science,settings};$('#app').innerHTML=shell((views[page]||today)()+(page==='settings'&&syncUI?syncUI.panel():''));document.body.classList.toggle('focus',focused);if(modal){const first=$('.modal input,.modal button,.modal select');first?.focus();}}
function openLesson(id){stopSpeaking();coachStep=0;coachPlaying=false;coachRevealed=false;active=null;clearInterval(timer);lessonId=id;lessonChoice=null;page='lesson';render();window.scrollTo({top:0,behavior:'instant'});}
function codeSetup(type){codeDrill={type,direction:'forward',batch:0,items:[],index:0,correct:0,checked:false};modal=`<h2>Train the permanent code</h2><p class="muted small">Produce the answer before checking. Both directions matter.</p><form id="code-start"><label class="field">Direction<select name="direction"><option value="forward">Code → image</option><option value="reverse">Image → code</option></select></label>${type==='numbers'?`<label class="field">Batch<select name="batch">${Array.from({length:10},(_,i)=>`<option value="${i}">${i}0–${i}9</option>`).join('')}</select></label>`:type==='cards'?`<label class="field">Suit<select name="batch">${suits.map((s,i)=>`<option value="${i}">${s[1]} ${s[2]}</option>`).join('')}</select></label>`:''}<div class="row"><button type="submit" class="btn">Start code practice</button>${btn('Close','close-modal','','outline')}</div></form>`;render();}
function showCodeQuestion(){const d=codeDrill;if(d.index>=d.items.length){modal=`<h2>Code practice complete.</h2><p>${d.correct} of ${d.items.length} correct in the ${d.direction==='forward'?'code-to-image':'image-to-code'} direction.</p><p class="fineprint">This is component practice. It does not count as a fresh sequence mastery pass.</p><div class="row">${btn('Practice the other direction','code-other')}${btn('Done','close-modal','','light')}</div>`;render();return;}const item=d.items[d.index],cue=d.direction==='forward'?item.code:item.image;modal=`<p class="eyebrow">CODE PRACTICE · ${d.index+1} / ${d.items.length}</p><p class="small muted">${d.direction==='forward'?'Which image belongs to this code?':'Which code belongs to this image?'}${d.type==='cards'&&d.direction==='reverse'?' Use a card code such as AS or 10H.':''}</p><div class="drill-word">${d.direction==='reverse'?picture(cue,{label:true}):esc(cue)}</div><form id="code-answer"><label class="field">Your answer<input name="answer" autocomplete="off" required maxlength="120" ${d.checked?'disabled':''}></label>${d.checked?`<div class="feedback">${d.lastCorrect?'✓ Correct.':'Keep building this connection.'} Answer: <strong>${esc(d.direction==='forward'?item.image:item.code)}</strong></div>${btn('Next →','code-next')}`:'<button class="btn" type="submit">Check answer</button>'} ${btn('Close','close-modal','','outline')}</form>`;render();}
function openNote(id){noteReview={id,shown:false};showNote();}
function showNote(){const n=p().notes.find(n=>n.id===noteReview.id);modal=`<p class="eyebrow">MY NOTEBOOK · ACTIVE RECALL</p><h2>${esc(n.question)}</h2>${noteReview.shown?`<div class="callout"><p style="white-space:pre-wrap">${esc(n.answer)}</p>${n.cue?`<p class="small muted" style="white-space:pre-wrap">Your cue: ${esc(n.cue)}</p>`:''}</div><p class="small muted">Compare with what you produced. Self-assessment is separate from scored drills.</p><div class="row">${btn('I recalled it','note-grade','data-correct="1"')}${btn('Needs practice','note-grade','data-correct="0"','light')}</div>`:`<p class="small muted">Say or write your answer before revealing it. Try explaining the idea in your own words, too.</p><label class="field">My recall (optional)<textarea maxlength="2000" placeholder="What can you bring back?"></textarea></label>${btn('Reveal & compare','note-reveal')}`}<button class="linkbtn" data-action="close-modal" style="margin-top:15px;display:block">Close</button>`;render();}
function exportFile(name,content,type){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function exportCSV(){const fields=['date','mode','items','accuracy_percent','encoding_seconds','recall_seconds','response_mode','delayed','assisted','delay_hours'];const rows=p().history.map(h=>[new Date(h.at).toISOString(),h.mode,h.count,Math.round(h.accuracy*100),Math.round(h.encodingMs/1000),Math.round(h.recallMs/1000),h.responseMode||'typed',!!h.delayed,!!h.assisted,Math.round((h.delayMs||0)/3600000)]);exportFile('mentalist-memory-practice.csv',[fields,...rows].map(row=>row.join(',')).join('\n'),'text/csv');}
let paoScene=null,editingRoute=null;
document.addEventListener('click',async e=>{
 const b=e.target.closest('[data-page],[data-action]');if(!b)return;if(b.dataset.page){e.preventDefault();go(b.dataset.page);return;}const action=b.dataset.action;const id=b.dataset.id;
 if(action.startsWith('sync-')){await syncUI.action(action);return;}
 if(action==='coach-step'){coachStep=Math.max(0,Math.min(2,Number(b.dataset.index)));coachPlaying=false;coachRevealed=false;stopSpeaking();render();}
 else if(action==='coach-play'){coachPlaying=!coachPlaying;render();}
 else if(action==='coach-reveal'){coachRevealed=!coachRevealed;render();}
 else if(action==='listen-coach'){const frame=visualLessons[lessonId][coachStep];speak(frame.title+' '+frame.caption);}
 else if(action==='listen-study'){speak($('#study-caption')?.textContent||'');}
 else if(action==='animate-pair'){const changed=selectedMotion!==b.dataset.motion;selectedMotion=b.dataset.motion;studyMotion=changed||!studyMotion;render();}
 else if(action==='place-picture'){if(!active.placed.includes(active.studyIndex))active.placed.push(active.studyIndex);render();}
 else if(action==='study-next'||action==='study-back'){stopSpeaking();studyMotion=false;active.studyIndex=Math.max(0,Math.min(active.set.items.length-1,active.studyIndex+(action==='study-next'?1:-1)));render();}
 else if(action==='recall-next'||action==='recall-back'){captureAnswers();active.recallIndex=Math.max(0,Math.min(active.set.items.length-1,active.recallIndex+(action==='recall-next'?1:-1)));render();}
 else if(action==='choose-picture'){const idx=active.set.order[active.recallIndex];active.answers[idx]=b.dataset.answerValue;render();}
 else if(action==='lesson')openLesson(id);
 else if(action==='answer-lesson'){const l=chapters.flatMap(c=>c.lessons).find(l=>l.id===lessonId);lessonChoice=Number(b.dataset.index);if(lessonChoice===l.answer&&!p().lessons.includes(l.id)){p().lessons.push(l.id);save();}render();}
 else if(action==='next-lesson'){const all=chapters.flatMap(c=>c.lessons),i=all.findIndex(l=>l.id===id);if(i<all.length-1)openLesson(all[i+1].id);else go('progress');}
 else if(action==='setup'){if(active&&!confirm('Leave this unfinished drill?'))return;active=null;clearInterval(timer);page='train';setupMode=b.dataset.mode;render();window.scrollTo({top:0,behavior:'instant'});}
 else if(action==='studio'){active=null;setupMode=null;render();}
 else if(action==='recall')toRecall();
 else if(action==='pause'&&active)togglePause();
 else if(action==='focus'){captureAnswers();focused=!focused;render();}
 else if(action==='submit-recall')submitRecall();
 else if(action==='another-look'){captureAnswers();active.recallMs+=Date.now()-active.recallStart;active.assisted=true;active.phase='study';active.studyIndex=0;active.studyStart=Date.now();active.limit=0;active.answers=active.answers.map(()=> '');render();}
 else if(action==='fresh'){const mode=b.dataset.mode;active=null;setupMode=mode;render();}
 else if(action==='finish'||action==='finish-progress'){active=null;go(action==='finish'?'today':'progress');}
 else if(action==='review-set'){const r=p().reviews.find(r=>r.id===id);if(!r||r.due>Date.now())return;const set=JSON.parse(JSON.stringify(r));set.id=r.setId;active={studyIndex:0,recallIndex:0,placed:[],choices:makeChoices(set),set,phase:'recall',start:Date.now(),studyStart:0,encodingMs:0,recallStart:Date.now(),recallMs:0,limit:0,remaining:0,paused:false,assisted:false,answers:r.items.map(()=>''),reviewId:r.id};page='train';render();startClock();}
 else if(action==='tool-tab'){page='toolkit';toolTab=b.dataset.tab;render();window.scrollTo({top:0,behavior:'instant'});}
 else if(action==='route-practice'){const r=p().routes.find(r=>r.id===id);page='train';setupMode='palace';render();$('#route').value=id;$('#count').value=Math.min(r.locations.length,recommendCount(p(),'palace'));}
 else if(action==='route-edit'){const r=p().routes.find(r=>r.id===id);if(p().reviews.some(v=>v.routeId===id)){toast('This route is reserved for a retest. Create another route while you retain this list.');return;}editingRoute=id;modal=`<h2>Edit your route</h2><form id="edit-route-form"><label class="field">Route name<input name="name" value="${esc(r.name)}" maxlength="60" required></label><label class="field">Locations, one per line<textarea name="locations" rows="10" required>${esc(r.locations.join('\n'))}</textarea></label><div id="route-error" class="bad small" role="alert"></div><div class="row"><button class="btn" type="submit">Save route</button>${btn('Cancel','close-modal','','outline')}</div></form>`;render();}
 else if(action==='code-setup')codeSetup(b.dataset.code);
 else if(action==='code-next'){codeDrill.index++;codeDrill.checked=false;showCodeQuestion();}
 else if(action==='code-other'){codeDrill.direction=codeDrill.direction==='forward'?'reverse':'forward';codeDrill.index=0;codeDrill.correct=0;codeDrill.checked=false;codeDrill.items=shuffle(codeDrill.items);showCodeQuestion();}
 else if(action==='close-modal'){modal='';noteReview=null;render();}
 else if(action==='review-note')openNote(id);
 else if(action==='note-reveal'){noteReview.shown=true;showNote();}
 else if(action==='note-grade'){const n=p().notes.find(x=>x.id===noteReview.id);updateNote(n,b.dataset.correct==='1');save();modal='';noteReview=null;render();toast('Review saved. Next review: '+new Date(n.due).toLocaleString());}
 else if(action==='pao-examples'){const defaults={'12':{person:'pilot',action:'steering',object:'plane'},'34':{person:'baker',action:'kneading',object:'bread'},'56':{person:'drummer',action:'striking',object:'drum'}};for(const [k,v] of Object.entries(defaults))if(!p().pao[k])p().pao[k]=v;save();render();toast('Added examples to empty rows. Existing rows were preserved.');}
 else if(action==='pao-hide'){if(!paoScene)return;modal=`<p class="eyebrow">PAO · DECODE THE SCENE</p><h2>${esc(paoScene.text)}</h2><p class="small muted">Recover person code + action code + object code.</p><form id="pao-answer-form"><label class="field">Six-digit code<input name="answer" inputmode="numeric" maxlength="6" required pattern="[0-9]{6}"></label><button class="btn" type="submit">Check decoding</button> ${btn('Close','close-modal','','outline')}</form>`;render();}
 else if(action==='export')exportFile('mentalist-memory-backup.json',JSON.stringify(state,null,2),'application/json');
 else if(action==='export-csv')exportCSV();
});
document.addEventListener('change',e=>{if(e.target.id==='profile-select'){state.active=e.target.value;syncUI?.hideCode();save();render();}});
document.addEventListener('input',e=>{if(e.target.matches('[data-answer]')&&active)active.answers[Number(e.target.dataset.answer)]=e.target.value;});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&modal){modal='';render();}if(e.key==='Tab'&&modal){const els=[...document.querySelectorAll('.modal button:not(:disabled),.modal input:not(:disabled),.modal select,.modal textarea,.modal a')];if(!els.length)return;const first=els[0],last=els.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
document.addEventListener('submit',async e=>{
 const f=e.target;if(!f.id)return;e.preventDefault();const data=new FormData(f),value=n=>String(data.get(n)||'').trim();
 if(f.id==='sync-join-form'){$('#sync-code-input')?.blur?.();await syncUI.join(value('syncCode'));return;}
 if(f.id==='setup-form'){p().minutes=Number($('#minutes').value);save();begin(setupMode,Number($('#count').value),Number($('#limit').value),$('#route')?.value);}
 else if(f.id==='route-form'||f.id==='edit-route-form'){const locs=value('locations').split('\n').map(x=>x.trim()).filter(Boolean);if(locs.length<3||locs.length>50||locs.some(x=>x.length>100)||new Set(locs.map(x=>x.toLowerCase())).size!==locs.length){$('#route-error').textContent='Use 3–50 distinct locations, each no longer than 100 characters.';return;}if(!value('name'))return;if(f.id==='route-form'){if(p().routes.length>=50){toast('You can keep up to 50 routes. Edit an existing route.');return;}p().routes.push({id:uid(),name:value('name'),locations:locs});}else{const r=p().routes.find(r=>r.id===editingRoute);r.name=value('name');r.locations=locs;modal='';}save();render();toast('Route saved. Rehearse the locations before adding items.');}
 else if(['number-form','card-form','peg-form'].includes(f.id)){const kind=f.id==='number-form'?'num':f.id==='card-form'?'card':'peg',key=kind==='num'?'numberImages':kind==='card'?'cardImages':'pegs';const vals=p()[key].map((_,i)=>value(`${kind}-${i}`));if(vals.some(x=>!x)){toast('Every code needs an image.');return;}if(new Set(vals.map(x=>x.toLowerCase())).size!==vals.length){toast('Use distinct images so reverse decoding has a single answer.');return;}p()[key]=vals;save();toast('Codebook saved.');}
 else if(f.id==='pao-form'){const code=value('code');const row={person:value('person'),action:value('action'),object:value('object')};if(!Object.values(row).every(Boolean))return;for(const [k,r]of Object.entries(p().pao)){if(k!==code&&Object.keys(row).some(field=>match(row[field],r[field]))){toast('Choose distinct people, actions, and objects for unambiguous decoding.');return;}}p().pao[code]=row;save();render();toast('PAO row saved.');}
 else if(f.id==='pao-scene-form'){const digits=value('digits'),a=p().pao[digits.slice(0,2)],b=p().pao[digits.slice(2,4)],c=p().pao[digits.slice(4,6)];if(!a||!b||!c){$('#pao-scene').textContent='Save a PAO row for each two-digit pair first.';return;}paoScene={digits,text:`${a.person} ${b.action} ${c.object}`};$('#pao-scene').innerHTML=`<div class="callout"><p class="eyebrow">${digits.match(/../g).join(' · ')}</p><h3>${esc(paoScene.text)}</h3><p class="small muted">Person → action → object. Imagine the scene, then practice decoding.</p>${btn('Hide code & decode','pao-hide','','light small')}</div>`;}
 else if(f.id==='pao-answer-form'){const correct=match(value('answer'),paoScene.digits);modal=`<h2>${correct?'Correct decoding.':'Revisit the components.'}</h2><p>${esc(paoScene.text)} → <strong>${paoScene.digits.match(/../g).join(' ')}</strong></p><p class="fineprint">Check person, action, and object independently. This component exercise does not award a chapter mastery pass.</p>${btn('Done','close-modal')}`;render();}
 else if(f.id==='note-form'){if(!value('question')||!value('answer'))return;p().notes.unshift({id:uid(),question:value('question'),answer:value('answer'),cue:value('cue'),due:Date.now()+DAY,interval:0,reviews:0});save();render();toast('Note saved. First review is due tomorrow.');}
 else if(f.id==='code-start'){const d=codeDrill;d.direction=value('direction');d.batch=Number(value('batch')||0);const items=d.type==='pegs'?p().pegs.map((image,i)=>({code:String(i+1),image})):d.type==='numbers'?p().numberImages.map((image,i)=>({code:String(i).padStart(2,'0'),image})).slice(d.batch*10,d.batch*10+10):cards.map((c,i)=>({code:c.code,image:p().cardImages[i]})).slice(d.batch*13,d.batch*13+13);d.items=shuffle(items);showCodeQuestion();}
 else if(f.id==='code-answer'){const d=codeDrill;if(d.checked)return;const item=d.items[d.index];d.lastCorrect=match(value('answer'),d.direction==='forward'?item.image:item.code);if(d.lastCorrect)d.correct++;d.checked=true;showCodeQuestion();}
 else if(f.id==='rename-form'){if(!value('name'))return;p().name=value('name');save();render();toast('Name saved.');}
 else if(f.id==='new-profile-form'){if(!value('name'))return;if(state.profiles.length>=20){toast('This backup supports up to 20 profiles.');return;}const profile=newProfile(value('name'));state.profiles.push(profile);state.active=profile.id;save();render();toast('Created a separate local profile.');}
 else if(f.id==='import-form'){try{const file=data.get('backup');if(!file||file.size>10*1024*1024)throw Error('Choose a JSON backup smaller than 10 MB.');const incoming=JSON.parse(await file.text(),(key,v)=>['__proto__','constructor','prototype'].includes(key)?undefined:v);if(!validStore(incoming))throw Error('This file is not a valid Mentalist Memory version 1 backup.');if(state.profiles.length+incoming.profiles.length>20)throw Error('Import would exceed 20 profiles. Choose a smaller backup.');for(const profile of incoming.profiles){profile.id=uid();profile.name=profile.name.slice(0,49)+' (imported)';state.profiles.push(profile);}save();render();toast('Imported profiles as new copies. Switch learner to use them.');}catch(err){$('#import-error').textContent=err.message;}}
});
syncUI=setupSync({storage:localStorage,getState:()=>state,commit:commitState,canApply:()=>!storageWarning&&!active&&!modal&&!['toolkit','lesson'].includes(page)&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName),notify:toast,rerender:render});
render();
